import sys
from collections import deque

def find_position(grid, target):
    for i in range(2):
        for j in range(len(grid[0])):
            if grid[i][j] == target:
                return i, j
    return -1, -1

def bfs(grid, start, target):
    directions = {'u': (-1, 0), 'd': (1, 0), 'l': (0, -1), 'r': (0, 1)}
    queue = deque([(start, '')])
    visited = set()
    visited.add(start)

    while queue:
        (x, y), path = queue.popleft()
        if (x, y) == target:
            return path
        for move, (dx, dy) in directions.items():
            nx, ny = x + dx, y + dy
            if 0 <= nx < 2 and 0 <= ny < len(grid[0]) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), path + move))
    return None

